function o(n){return n.paymentExemption==="half"||n.paymentExemption==="full"||n.paymentExemption==="none"?n.paymentExemption:n.paymentExempt?"full":"none"}function m(n){let t=o(n);return t==="full"?0:t==="half"?.5:1}function y(n){return o(n)==="full"}function x(n){return n.filter(t=>t.active!==!1&&m(t)>0)}function l(n){return n.filter(t=>t.active!==!1).reduce((t,e)=>t+m(e),0)}function p(n,t){return!t||t<=0?0:n/t}function f(n,t){let e=n.installments||1;return p(n.totalAmount,t)/e}function c(n,t,e){return f(n,l(t))*m(e)}function b(n){return n?Number.isInteger(n)?String(n):n.toFixed(1).replace(".",","):"0"}function P(n){return n==="full"?"Liberado":n==="half"?"Liberado 50%":""}function s(n,t,e){return`${n}-${t}-${e}`}function d(n){let t=new Map;for(let e of n){let a=s(e.playerId,e.tournamentId,e.installmentNumber);t.set(a,(t.get(a)??0)+(Number(e.amount)||0))}return t}function g(n,t){return t<=1||n+1>=t?"paid":n<=0?"unpaid":"partial"}function E(n,t){return Math.max(0,Math.round((n-t)*100)/100)}function I(n,t,e,a,u){return n.filter(r=>r.playerId===t&&r.tournamentId===e&&r.installmentNumber===a&&r.id!==u).reduce((r,i)=>r+(Number(i.amount)||0),0)}export{o as a,m as b,y as c,x as d,l as e,p as f,f as g,c as h,b as i,P as j,s as k,d as l,g as m,E as n,I as o};
